  perspective: 1000px;
  margin-top: 10px;
}

.receipt-card-3d {
  width: 100%;
  height: auto;
  min-height: 220px;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  cursor: pointer;
  will-change: transform; /* 告诉浏览器这个元素会变，请提前准备好显卡资源 */
  z-index: 1; /* 提升层级，防止被背景融合 */
}
.receipt-card-3d.flipped {
  transform: rotateY(180deg);
}
.receipt-card-3d .card-face {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: #fff;
  border-radius: 12px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);
  overflow: hidden;
  display: flex;
  flex-direction: column;
