   =============================================== */
.sync-memo-widget {
  position: absolute;
  top: 70px; /* 停靠在聊天页 Header 下方 */
  right: 20px;
  width: 240px;
  background: rgba(253, 251, 247, 0.95); /* 呼应系统的奶油白底色 */
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
  z-index: 1000;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.25, 1, 0.5, 1);
  transform-origin: top right;
  opacity: 1;
}
.sync-memo-widget.hidden {
  opacity: 0;
  pointer-events: none;
  transform: scale(0.95);
}
.sync-memo-widget.collapsed {
  width: 120px;
}
.sync-memo-widget.collapsed .sync-memo-body {
  max-height: 0;
  opacity: 0;
  pointer-events: none;
}
.sync-memo-widget.collapsed .sync-memo-header {
  border-bottom-color: transparent;
}
.sync-memo-widget.collapsed .sync-memo-header .chevron {
  transform: rotate(180deg);
}
.sync-memo-widget .sync-memo-header {
  padding: 10px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  transition: background 0.2s;
}
.sync-memo-widget .sync-memo-header:active {
  background: rgba(0, 0, 0, 0.03);
}
.sync-memo-widget .sync-memo-header .left {
  display: flex;
  align-items: center;
  gap: 8px;
}
.sync-memo-widget .sync-memo-header .left .dot {
  width: 6px;
  height: 6px;
  background: #1a1a1a;
  border-radius: 50%;
}
.sync-memo-widget .sync-memo-header .left .title {
  font-size: 10px;
  font-weight: 800;
  color: #1a1a1a;
  letter-spacing: 1px;
  font-family: "Helvetica Neue", Arial, sans-serif;
}
.sync-memo-widget .sync-memo-header .right {
  display: flex;
  align-items: center;
}
.sync-memo-widget .sync-memo-header .chevron {
  width: 14px;
  height: 14px;
  color: #888;
  transition: transform 0.4s;
}
.sync-memo-widget .sync-memo-body {
  max-height: 350px;
  opacity: 1;
  transition: all 0.4s ease;
  display: flex;
  flex-direction: column;
}
.sync-memo-widget .sync-memo-body ul {
