  display: flex; /* 1. 将卡片设置为 Flex 容器 */
  flex-direction: column; /* 2. 让子元素（header, body, footer）垂直排列 */
  max-height: 85vh; /* 3. 限制弹窗最大高度为视窗的85%，超出则触发内部滚动 */
  /* ▲▲▲【核心修改】到这里结束 ▲▲▲ */
}

/* 1. 头部：头像区 */
.line-header {
  padding: 30px 0 20px;
  display: flex;
  justify-content: center;
  background-color: #fff;
  flex-shrink: 0;
}

.char-modal-avatar-container {
  width: 100px;
  height: 100px;
  border: 1px solid #000; /* 头像黑边框 */
  border-radius: 50%;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  background: #f8f8f8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.char-modal-avatar-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* 占位符样式 */
.avatar-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: #000;
}

.avatar-placeholder svg {
  width: 24px;
  height: 24px;
  stroke-width: 1.5;
}

.avatar-placeholder span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

/* 2. 内容区 */
.line-body {
  padding: 0 24px 20px; /* 增加了底部内边距，让滚动到底部时更美观 */
  display: flex;
  flex-direction: column;
  gap: 20px;
  /* ▼▼▼【核心修改】从这里开始 ▼▼▼ */
  flex-grow: 1; /* 1. 让内容区占据 header 和 footer 之间的所有可用空间 */
  overflow-y: auto; /* 2. 【关键】当内容高度超出时，自动显示垂直滚动条 */
  /* ▲▲▲【核心修改】到这里结束 ▲▲▲ */
}

/* 输入组：标签 + 下划线输入框 */
.line-input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.line-input-group label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  color: #000;
  text-transform: uppercase;
  opacity: 0.6;
}

.line-input {
  border: none;
  border-bottom: 1px solid #e0e0e0; /* 默认浅灰线 */
  padding: 8px 0;
  font-size: 16px;
  font-weight: 600;
  color: #000;
  background: transparent;
  border-radius: 0;
  transition: border-color 0.2s;
}

.line-input:focus {
  outline: none;
  border-bottom: 2px solid #000; /* 聚焦变黑粗线 */
}

/* 下拉框容器 */
.select-wrapper {
  position: relative;
}

.line-select {
  width: 100%;
  border: none;
  border-bottom: 1px solid #e0e0e0;
  padding: 8px 0;
  font-size: 15px;
  color: #000;
  background: transparent;
  border-radius: 0;
  appearance: none; /* 移除默认箭头 */
  cursor: pointer;
}

.line-select:focus {
  outline: none;
  border-bottom: 2px solid #000;
}

.select-arrow {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  pointer-events: none;
  fill: none;
  stroke: #000;
  stroke-width: 2;
}

