  padding: 10px 0;
  list-style: none;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  flex-shrink: 0;
}
.line-details summary svg {
  width: 18px;
  height: 18px;
  transition: transform 0.2s ease;
}

/* 隐藏 Chrome/Safari 默认的折叠箭头 */
.line-details summary::-webkit-details-marker {
  display: none;
}

/* 当折叠区域展开时 (<details> 标签拥有 open 属性)，旋转 SVG 图标（让 + 变成 x） */
.line-details[open] summary svg {
  transform: rotate(45deg);
}

/* 展开后的内容区域 */
.details-content {
  padding-bottom: 15px;
}

/* 角色设定的文本输入框 (Textarea) */
.line-textarea {
  width: 100%;
  border: none;
  background: #f9f9f9;
  padding: 10px;
  font-size: 13px;
  line-height: 1.5;
  color: #333;
  height: 260px; /* 【修改】从 100px 增大到 150px，让文本框更高 */
  resize: none;
  box-sizing: border-box;
}

/* 文本框获得焦点时的样式 */
.line-textarea:focus {
  outline: 1px solid #000;
  background: #fff;
}

.line-action-btn {
  padding: 10px 16px;
  border: 1px solid #000;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: all 0.2s;
  background: #fff;
  flex-shrink: 0;
}
.line-action-btn svg {
  width: 20px;
  height: 20px;
}

.line-action-btn:active {
  background: #000;
  color: #fff;
}

.btn-content {
  display: flex;
  flex-direction: column;
}

.btn-title {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.btn-subtitle {
  font-size: 9px;
  opacity: 0.6;
  margin-top: 2px;
}

/* 3. 底部按钮区 */
.line-footer {
  display: flex;
  border-top: 1px solid #000; /* 分割线 */
  flex-shrink: 0;
}

.line-footer button {
  flex: 1;
  padding: 18px;
  border: none;
  background: #fff;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-line-secondary {
  color: #000;
  border-right: 1px solid #000; /* 中间分割线 */
}

.btn-line-secondary:hover {
  background: #f0f0f0;
}

.btn-line-primary {
  background: #000 !important;
  color: #fff !important;
}

.btn-line-primary:hover {
  opacity: 0.9;
}

/* ==========================================================================
