}

/* 【新增】被选中正在编辑的 NPC 样式 */
.npc-item.editing {
  background-color: #f0f0f0;
  border-radius: 8px;
  padding-left: 8px;
  padding-right: 8px;
  border: 1px solid #000; /* 加个黑边框表示选中 */
}

/* 列表项样式 */
.npc-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid #f2f2f7; /* 极细的分割线 */
}

.npc-item:last-child {
  border-bottom: none;
}

.npc-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.npc-info span {
  font-size: 16px;
  font-weight: 600;
  color: #1c1c1e;
}

.npc-info small {
  font-size: 12px;
  color: #8e8e93;
}

/* 删除按钮：灰色小圆圈 */
.npc-delete-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #f2f2f7;
  color: #8e8e93;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  cursor: pointer;
  transition: all 0.2s;
}

.npc-delete-btn:hover {
  background: #ff3b30; /* 悬停变红 */
  color: white;
}

/* 3. 输入区 (灰色背景块) */
.npc-input-area {
  background-color: #F9F9F9; /* 非常淡的灰底，区分输入区 */
  padding: 20px 24px;
  border-top: 1px solid #f0f0f0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.npc-input-row {
  display: flex;
  gap: 10px;
}

/* 输入框通用样式 */
.minimal-input {
  background: #ffffff;
  border: 1px solid #e5e5ea; /* 浅灰边框 */
  border-radius: 12px;
  padding: 12px;
  font-size: 14px;
  color: #1c1c1e;
  width: 100%;
  box-sizing: border-box;
  transition: border-color 0.2s;
  font-family: inherit;
}

.minimal-input:focus {
  outline: none;
  border-color: #000000; /* 聚焦时变成黑色边框 */
}

.minimal-input::placeholder {
  color: #c7c7cc;
}

.minimal-textarea {
  height: 70px;
  resize: none;
}

/* 添加按钮：纯黑块 */
.btn-minimal-black {
  background: #000000;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  padding: 12px;
  font-size: 14px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  transition: opacity 0.2s;
}

.btn-minimal-black:active {
  opacity: 0.7;
}

.btn-minimal-black svg {
  width: 16px;
  height: 16px;
}

/* 4. 底部完成按钮 */
.npc-footer {
  padding: 10px 24px 20px;
  background-color: #F9F9F9;
  text-align: center;
}

.btn-minimal-text {
  background: transparent;
  border: none;
  color: #8e8e93;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  padding: 10px 20px;
}

.btn-minimal-text:hover {
  color: #000;
}

/* 
 * ==========================================================================
 *   ▼▼▼ 新增/修复：位置发送模态框专属样式 ▼▼▼
 * ==========================================================================
 */
/* 模态框内的地图预览容器 */
#location-map-preview {
  width: 100%;
  height: 150px;
  border-radius: 10px;
  overflow: hidden;
  position: relative;
  background-color: var(--c-bg-secondary); /* 加载时的背景色 */
  margin-top: 15px;
  border: 1px solid var(--c-border-light);
}

/* 地图图片 */
#location-map-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 随机生成的红色图钉 */
#location-map-pin {
  position: absolute;
  width: 24px;
  height: 24px;
  /* 使用内联 SVG 作为图钉图标，无需外部图片文件 */
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23EA4335"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg>');
  background-size: contain;
  /* 关键：让图钉的尖端对准坐标点，而不是左上角 */
  transform: translate(-50%, -90%);
}

