  font-size: var(--font-sm);
  color: var(--c-text-secondary);
}

.sticker-drawer-actions {
  display: flex;
  gap: var(--space-sm);
}

.sticker-drawer-actions button {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  opacity: 0.5;
}

.sticker-drawer-actions button:hover {
  opacity: 1;
}

.sticker-drawer-actions svg {
  width: 18px;
  height: 18px;
  stroke: var(--c-text-secondary);
}

.sticker-drawer-chevron {
  margin-left: var(--space-md);
  transition: transform 0.3s ease;
}

.sticker-drawer-chevron svg {
  width: 20px;
  height: 20px;
  stroke: var(--c-text-tertiary);
  stroke-width: 2.5;
}

.sticker-drawer[open] > summary .sticker-drawer-chevron {
  transform: rotate(90deg);
}

.sticker-drawer-content {
  padding: 0 var(--space-lg) var(--space-lg);
}

/* 找到这个类，修改它的内容 */
.sticker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: var(--space-md);
  border-top: 1px solid var(--c-border);
  padding-top: var(--space-lg);
  /* ▼▼▼【新增】这一行是防止列表卡顿的神器！ ▼▼▼ */
  content-visibility: auto;
  contain-intrinsic-size: 100px 500px; /* 给一个预估高度 */
}

.sticker-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  aspect-ratio: 1/1;
  border-radius: var(--radius-md);
  background-color: var(--c-bg-secondary);
  padding: var(--space-xs);
  box-sizing: border-box;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
}

.sticker-item:hover {
  transform: scale(1.05);
  box-shadow: var(--shadow-md);
}

.sticker-item .sticker-image {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.sticker-item .sticker-explanation {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(0, 0, 0, 0.6);
  color: white;
  font-size: 11px;
  text-align: center;
  padding: 5px;
  margin: 0;
  opacity: 0;
  transition: opacity 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.sticker-item:hover .sticker-explanation {
  opacity: 1;
}

.sticker-delete-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 20px;
  height: 20px;
  background-color: rgba(0, 0, 0, 0.5);
  color: white;
  border: none;
  border-radius: 50%;
  font-size: 14px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 10;
}

.sticker-item:hover .sticker-delete-btn {
  opacity: 1;
}

/* --- 上传弹窗样式 --- */
.sticker-upload-modal {
  width: 90%;
  max-width: 420px;
}

#sticker-upload-unified-grouping {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  background-color: #f0f2f5;
  border-bottom: 1px solid #e5e5ea;
  flex-shrink: 0;
}

#sticker-upload-unified-grouping label {
  font-size: 14px;
  color: #636366;
  flex-shrink: 0;
}

#sticker-upload-unified-grouping select {
  flex-grow: 1;
  /* 移除了 width: 100% 因为 flex-grow 已经足够 */
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid #d1d1d6;
  background-color: #FFFFFF;
  font-size: 14px;
}

.sticker-upload-list {
  max-height: 55vh;
  overflow-y: auto;
  margin-bottom: var(--space-lg);
  border: 1px solid var(--c-border-light);
  border-radius: var(--radius-md);
}

.sticker-upload-dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-xl);
  text-align: center;
  color: var(--c-text-secondary);
  border: 2px dashed var(--c-border-light);
  border-radius: var(--radius-md);
  transition: background-color 0.2s ease, border-color 0.2s ease;
  cursor: pointer;
}

.sticker-upload-dropzone.dragover {
  background-color: #eef5ff;
  border-color: var(--c-accent);
}

.sticker-upload-dropzone svg {
  stroke: var(--c-text-tertiary);
  margin-bottom: var(--space-sm);
}

.sticker-upload-dropzone .file-input-label {
  color: var(--c-accent);
  font-weight: 500;
  cursor: pointer;
}

.sticker-upload-dropzone small {
  margin-top: var(--space-xs);
  font-size: var(--font-xs);
}

.sticker-upload-buttons {
  display: flex;
  justify-content: space-between;
  gap: var(--space-sm);
}

.sticker-upload-item {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border-bottom: 1px solid var(--c-border);
}

.sticker-upload-list > .sticker-upload-item:last-child {
  border-bottom: none;
}

.sticker-upload-item .preview-img {
  width: 60px;
  height: 60px;
  object-fit: contain;
  border-radius: var(--radius-sm);
  background-color: var(--c-bg-tertiary);
  flex-shrink: 0;
}

.sticker-upload-item .upload-details {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.sticker-upload-item .upload-details input, .sticker-upload-item .upload-details select {
  width: 100%;
  box-sizing: border-box;
  padding: 8px 12px;
  border: 1px solid var(--c-border-light);
  border-radius: var(--radius-sm);
  font-size: var(--font-sm);
  background-color: var(--c-bg-primary);
}

.sticker-upload-item .upload-details input:focus, .sticker-upload-item .upload-details select:focus {
  outline: none;
  border-color: var(--c-accent);
}

.sticker-upload-item .remove-upload-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  flex-shrink: 0;
  opacity: 0.6;
}

.sticker-upload-item .remove-upload-btn:hover {
  opacity: 1;
}

.sticker-upload-item .remove-upload-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--c-accent-red);
}

/* ========================================================== */
/* == 【新增 + 精修】设置页面在手机端的响应式微调 == */
/* ========================================================== */
@media (max-width: 600px) {
