  }
  .contact-info {
    gap: 0.51vw; /* 2px */
  }
  /* --- 输入框和按钮 --- */
  .styled-input {
    padding: 2.56vw; /* 10px */
  }
  .btn-group {
    margin-top: 7.69vw; /* 30px */
