/* 消除系统原生丑陋样式的下拉框 */
.api-custom-select {
  border: none;
  background: transparent;
  text-align: right;
  color: var(--c-text-secondary);
  outline: none;
  font-size: var(--font-md);
  /* 核心：抹除苹果/安卓默认的灰色外壳和箭头 */
  -webkit-appearance: none;
  appearance: none;
  /* 用背景图画一个极简的小箭头 */
  padding-right: 20px;
  background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="%238e8e93" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg"><polyline points="6 9 12 15 18 9"></polyline></svg>');
  background-repeat: no-repeat;
  background-position: right center;
  /* 让选中的文字顶住右边 */
  direction: rtl;
  /* 让点开的下拉菜单里文字恢复左对齐 */
}
.api-custom-select option {
  direction: ltr;
}

