#page-chat {
  display: flex;
  flex-direction: column;
}
#page-chat .chat-main-area {
  flex-grow: 1;
  overflow: hidden;
  background: linear-gradient(180deg, #f4f0ff 0%, #e9efff 100%);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  display: flex;
  flex-direction: column;
}
#page-chat .chat-main-area .app-content {
  flex-grow: 1;
  overflow-y: auto;
  padding-bottom: 10vh;
}

.chat-top-area {
  position: relative;
  z-index: 2;
  background-color: transparent;
  padding: 32px var(--space-lg) 8px;
  flex-shrink: 0;
}

.chat-search-bar {
  position: relative;
  margin-top: -10px;
  margin-bottom: var(--space-lg);
}
.chat-search-bar svg {
  position: absolute;
  left: 15px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  stroke: #b2b2b7;
  stroke-width: 2;
}
.chat-search-bar input {
  width: 100%;
  box-sizing: border-box;
  padding: 12px 15px 12px 40px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(0, 0, 0, 0.05);
  background-color: white;
  box-shadow: 0 2px 8px rgba(138, 109, 255, 0.08);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
  font-size: var(--font-sm);
}
.chat-search-bar input::placeholder {
  color: #b2b2b7;
}
.chat-search-bar input:focus {
  outline: none;
  border-color: rgba(138, 109, 255, 0.5);
  box-shadow: 0 4px 12px rgba(138, 109, 255, 0.12);
}

.chat-tabs {
  display: flex;
  gap: var(--space-lg);
  margin-bottom: var(--space-lg);
  font-weight: 600;
  font-size: var(--font-md);
}

#page-chat .chat-tabs[aria-hidden=true] {
  display: none;
}

.tab-item {
  color: var(--c-text-secondary);
  cursor: pointer;
  padding-bottom: var(--space-xs);
  position: relative;
}
.tab-item.active {
  color: #8a6dff;
}
.tab-item.active::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: #8a6dff;
}

.contacts-section {
  background-color: white;
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-md);
  overflow: hidden;
  box-shadow: 0 4px 12px rgba(32, 31, 35, 0.08);
}

.contacts-group {
  margin-bottom: var(--space-md);
}
.contacts-group summary {
  padding: 10px var(--space-md);
  font-size: var(--font-xs);
  color: var(--c-text-secondary);
  text-transform: uppercase;
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
}
.contacts-group summary::-webkit-details-marker {
  display: none;
}
.contacts-group summary::before {
  content: "▶";
  display: inline-block;
  margin-right: var(--space-sm);
  transition: transform 0.2s;
  font-size: 7px;
}
.contacts-group[open] > summary::before {
  transform: rotate(90deg);
}
.contacts-group .contacts-section {
  margin-bottom: 0;
}

#add-friend-btn,
#contacts-more-btn {
  display: none;
  position: absolute;
  right: var(--space-xs);
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  font-size: 0;
  line-height: 0;
}
#add-friend-btn svg,
#contacts-more-btn svg {
  width: 16px !important;
  height: 16px !important;
  min-width: 16px !important;
  max-width: 16px !important;
  min-height: 16px !important;
  max-height: 16px !important;
  flex: 0 0 16px !important;
  stroke: #333;
  fill: #333;
}

#contacts-menu {
  display: none;
  position: absolute;
  top: 45px;
  right: var(--space-md);
  background-color: var(--c-bg-primary);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  z-index: 120;
  overflow: hidden;
  width: 156px;
}
#contacts-menu .menu-item {
  padding: 12px var(--space-md);
  font-size: var(--font-sm);
  cursor: pointer;
  border-bottom: 1px solid var(--c-border);
}
#contacts-menu .menu-item:last-child {
  border-bottom: none;
}
#contacts-menu .menu-item:hover {
  background-color: var(--c-bg-tertiary);
}

#add-friend-list-container {
  max-height: 40vh; /* Limit height to allow scrolling */
  overflow-y: auto;
  padding: 0 8px;
}

.add-friend-item {
  display: flex;
  align-items: center;
  padding: 10px;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s;
}

.add-friend-item:hover {
  background-color: var(--c-bg-secondary);
}

.add-friend-item img {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  margin-right: 12px;
  object-fit: cover;
}

/* ========================================================== */
/* == 【新增】聊天页面在手机端的响应式调整 == */
