/* ▼▼▼ 轻量化极致细腻 Ins 风格 ▼▼▼ */
.ci-ins-card {
  width: 100%;
  background: #fff;
  border-radius: 16px; /* 缩小圆角，去粗犷感 */
  border: 1px solid rgba(0, 0, 0, 0.05); /* 极细极淡的边框 */
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.03); /* 轻盈的阴影 */
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  margin: 4px 0;
}

.ci-ins-summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 14px; /* 缩减 padding，显得更精致紧凑 */
  background: #fff;
  transition: background 0.2s ease;
}

.ci-ins-summary:active {
  background: #fcfcfc;
}

.ci-ins-summary::-webkit-details-marker {
  display: none;
}

.ci-ins-summary-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ci-ins-avatars {
  display: flex;
  position: relative;
}

.ci-ins-avatars img {
  width: 36px; /* 头像稍微缩小 */
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid #fff;
  background: #f5f5f5;
}

.ci-ins-avatars .ava-1 {
  position: relative;
  z-index: 2;
}

.ci-ins-avatars .ava-2 {
  margin-left: -12px;
  position: relative;
  z-index: 1;
}

.ci-ins-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ci-ins-title {
  font-size: 14px;
  font-weight: 600;
  color: #222;
}

.ci-ins-sub {
  font-size: 10px;
  color: #999;
  font-weight: 500;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.ci-ins-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #bcbcbc; /* 纯粹的极简箭头，无框 */
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.ci-ins-card[open] .ci-ins-arrow {
  transform: rotate(180deg);
  color: #666;
}

.ci-ins-body {
  border-top: 1px solid rgba(0, 0, 0, 0.03);
  background: #fafafa; /* 对话区有一点点浅灰底，区分层次 */
}

.ci-ins-thread {
  padding: 10px 12px 12px; /* 减小卡片内部的整体留白 */
  display: flex;
  flex-direction: column;
  gap: 8px; /* 缩减消息之间的间距 */
  max-height: 320px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.ci-ins-msg {
  display: flex;
  align-items: flex-start;
  gap: 6px; /* 拉近小头像和气泡的距离 */
}

.ci-ins-msg.speaker2 {
  flex-direction: row-reverse;
}

.ci-ins-avatar {
  width: 22px; /* 小头像再缩小一点，增加精致感 */
  height: 22px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.ci-ins-content {
  display: flex;
  flex-direction: column;
  min-width: 0;
  max-width: 72%;
}

.ci-ins-msg.speaker1 .ci-ins-content {
  align-items: flex-start;
}

.ci-ins-msg.speaker2 .ci-ins-content {
  align-items: flex-end;
}

.ci-ins-name {
  font-size: 9px;
  color: #999;
  line-height: 1.2;
  margin-bottom: 2px; /* 缩减名字和气泡的间距 */
  padding: 0 2px;
  transform: scale(0.9); /* 弱化名字显示 */
  transform-origin: left bottom;
}

.ci-ins-msg.speaker2 .ci-ins-name {
  transform-origin: right bottom;
}

/* ▼▼▼ 核心修改：极致紧凑的小气泡 ▼▼▼ */
.ci-ins-bubble {
  box-sizing: border-box;
  max-width: 100%;
  padding: 7px 9px; /* 小气泡留白，不吃全局消息气泡的 padding */
  font-size: 11px; /* 比正文小一级 */
  line-height: 1.45;
  color: #333;
}

.ci-ins-msg.speaker1 .ci-ins-bubble {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 12px 12px 12px 2px; /* 更锐利的水滴角 */
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
}

.ci-ins-msg.speaker2 .ci-ins-bubble {
  background: #f0f0f0; /* 非常淡的浅灰 */
  border: 1px solid transparent;
  border-radius: 12px 12px 2px 12px;
}

.message-bubble.is-char-interaction-card .ci-ins-text {
  margin: 0;
  padding: 0;
  font-size: inherit;
  line-height: inherit;
  word-break: break-word;
}

.ci-ins-trans {
  margin-top: 4px;
  font-size: 10px;
  color: #999;
}

/* ▲▲▲ 替换结束 ▲▲▲ */
.ci-ins-footer {
  text-align: center;
  font-size: 9px;
  color: #ccc;
  padding: 14px;
  font-weight: 700;
  letter-spacing: 1px;
}

/* ▲▲▲ 架构结束 ▲▲▲ */
@media (max-width: 380px) {
  .message-bubble.is-char-interaction-card {
    max-width: calc(100vw - 24px);
  }
  .ci-card summary {
    gap: 8px;
    padding-left: 9px;
    padding-right: 9px;
  }
  .ci-avatar {
    width: 31px;
    height: 31px;
  }
  .ci-card-title {
    font-size: 12px;
  }
  .ci-card-thread {
    padding-left: 9px;
    padding-right: 9px;
  }
}
