    height: 5.64vw; /* 22px */
    margin-right: 3.07vw; /* 12px */
  }
  #time-settings-modal .radio-custom-icon::before {
    width: 5.12vw; /* 20px */
    height: 5.12vw; /* 20px */
  }
  #time-settings-modal .radio-custom-icon::after {
    left: 1.28vw; /* 5px */
    top: 1.28vw; /* 5px */
    width: 3.07vw; /* 12px */
    height: 3.07vw; /* 12px */
  }
  #time-settings-modal .radio-label {
    /* 【修改】单选框文字固定为 16px */
