  font-weight: 600;
  line-height: 1.5;
}
.sleep-settings-item .sleep-settings-current::before {
  content: "SLEEP PROJECTION / 睡眠推演";
  display: block;
  margin-bottom: 4px;
  color: #888888; /* 灰色英文字母 */
