  letter-spacing: 1px;
}
.sleep-settings-item .sleep-settings-hint {
  margin: 7px 0 0 32px;
  color: var(--c-text-tertiary, #999);
  font-size: 10px;
  line-height: 1.4;
}
.sleep-settings-item .sleep-settings-controls {
  display: none;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0 0 32px;
}
.sleep-settings-item .sleep-settings-controls label {
  min-width: 0;
  color: var(--c-text-secondary, #8e8e93);
  font-size: 10px;
}
.sleep-settings-item .sleep-settings-controls label span {
  display: block;
  margin-bottom: 5px;
}
.sleep-settings-item .sleep-settings-controls input {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 7px 5px;
  border: 1px solid var(--c-border-light, #e5e5e5);
  border-radius: var(--radius-sm, 8px);
  background: var(--c-bg-tertiary, #f8f8f8);
  color: var(--c-text-primary, #1c1c1e);
  font-size: 11px;
}
.sleep-settings-item .sleep-settings-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  margin: 12px 0 0 32px;
}
.sleep-settings-item .sleep-settings-actions:has(.sleep-settings-undo:not([hidden])) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.sleep-settings-item .sleep-settings-actions button {
  width: 100%;
  min-width: 0;
  min-height: 36px;
  box-sizing: border-box;
  padding: 8px 10px;
  border-radius: var(--radius-sm, 8px);
  font-size: 11px;
  line-height: 1.2;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}
.sleep-settings-item .sleep-settings-apply {
  border: 1px solid var(--c-text-primary, #1c1c1e);
  background: var(--c-text-primary, #1c1c1e);
  color: var(--c-bg-primary, #fff);
}
.sleep-settings-item .sleep-settings-apply:disabled {
  border-color: var(--c-border-light, #e5e5e5);
  background: var(--c-bg-tertiary, #f8f8f8);
  color: var(--c-text-tertiary, #c7c7cc);
  opacity: 0.85;
  cursor: default;
}
.sleep-settings-item .sleep-settings-undo {
  border: 1px solid var(--c-border-light, #e5e5e5);
  background: transparent;
  color: var(--c-text-secondary, #8e8e93);
}
.sleep-settings-item .sleep-settings-undo:hover, .sleep-settings-item .sleep-settings-undo:active {
  border-color: var(--c-text-secondary, #8e8e93);
  background: var(--c-bg-secondary, #f2f2f5);
  color: var(--c-text-primary, #1c1c1e);
}
@media (max-width: 360px) {
  .sleep-settings-item .sleep-settings-controls {
    grid-template-columns: 1fr 1fr;
  }
}

