.sleep-schedule-select-modal {
  position: relative;
  width: min(88%, 360px) !important;
  max-width: 360px !important;
  padding: 22px 18px 18px !important;
  overflow: hidden;
  border: 1px solid #EADFD7;
  border-radius: 26px !important;
  background: #FFFDF9 !important;
  box-shadow: 0 24px 60px rgba(92, 84, 77, 0.16), 0 4px 14px rgba(163, 149, 143, 0.08);
}

.sleep-schedule-select-modal::before {
  content: "SLEEP PLAN / SETTING SYNC";
  display: block;
  padding-bottom: 10px;
  border-bottom: 1px solid #EDE3DB;
  background: linear-gradient(90deg, #D8B7A8 0 26%, transparent 26% 100%) bottom left/100% 2px no-repeat;
  color: #A9897A;
  font: 700 9px/1.2 Georgia, serif;
  letter-spacing: 1.6px;
}

.sleep-schedule-select-modal::after {
  content: "";
  position: absolute;
  right: -42px;
  bottom: -52px;
  width: 124px;
  height: 124px;
  border: 1px solid rgba(199, 167, 143, 0.22);
  border-radius: 50%;
  pointer-events: none;
}

