  min-height: 54px;
  box-sizing: border-box;
  padding: 11px 13px;
  border: 1px solid #EDE3DB;
  border-radius: 16px;
  background: #FFF;
  color: #5C544D;
  transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

.sleep-schedule-select-modal .selection-list-item:hover,
.sleep-schedule-select-modal .selection-list-item:active {
  border-color: #D8B7A8;
