}

.sleep-schedule-select-modal .item-text {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  color: #5C544D;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.sleep-schedule-select-modal .item-text::after {
  content: "SELECT / 选择";
  color: #B09D91;
  font: 700 8px/1.2 Georgia, serif;
  letter-spacing: 1px;
}

.sleep-schedule-select-modal .selection-list-item::after {
  content: "→";
  flex: 0 0 auto;
  color: #C7A78F;
  font-size: 19px;
