}

.sleep-schedule-select-modal .selection-list-item[data-id=sync] .item-text::after {
  content: "SYNC / 重新推演后续安排";
}

.sleep-schedule-select-modal .selection-list-item[data-id=only] .item-text::after {
  content: "KEEP / 保留当前行程";
}

.sleep-schedule-select-modal .selection-list-item[data-id=cancel] .item-text::after {
  content: "CANCEL / 撤回本次修改";
}

