/* --- 背景装饰元素 --- */
#bg-activity-modal-overlay {
  overflow: hidden;
}
#bg-activity-modal-overlay .magnetic-decor-plus, #bg-activity-modal-overlay .magnetic-decor-minus {
  position: absolute;
  font-weight: 900;
  color: rgba(255, 255, 255, 0.1);
  font-family: sans-serif;
  pointer-events: none;
  z-index: 0;
}
#bg-activity-modal-overlay .magnetic-decor-plus {
  top: 10%;
  right: -5%;
  font-size: 300px;
  transform: rotate(15deg);
}
#bg-activity-modal-overlay .magnetic-decor-plus::before {
  content: "+";
}
#bg-activity-modal-overlay .magnetic-decor-minus {
  bottom: 10%;
  left: -5%;
  font-size: 400px;
  transform: rotate(-15deg);
}
#bg-activity-modal-overlay .magnetic-decor-minus::before {
  content: "−";
}

/* --- 卡片本体 --- */
.magnetic-card {
  position: relative;
  background-color: #ffffff;
  border-radius: 22px;
  width: 90%;
  max-width: 400px;
  padding: 0;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 1;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* --- 头部 --- */
.magnetic-header {
  padding: 24px 24px 10px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.magnetic-header .header-text {
  display: flex;
  flex-direction: column;
  /* 【修改】确保文字和容器都左对齐 */
  align-items: flex-start;
  text-align: left;
}
.magnetic-header .header-text .title {
  font-size: 22px;
  font-weight: 800;
  color: #1a1a1a;
  margin: 0;
  letter-spacing: -0.5px;
}
.magnetic-header .header-text .subtitle {
  font-size: 12px;
  color: #a0a0a0;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-top: 4px;
}
.magnetic-header .magnetic-close-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #f4f4f4;
  border: none;
  color: #1a1a1a;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}
.magnetic-header .magnetic-close-btn svg {
  width: 20px;
  height: 20px;
  stroke-width: 2.5;
}
.magnetic-header .magnetic-close-btn:hover {
  background: #e0e0e0;
  transform: rotate(90deg);
}

/* --- 滚动内容区 --- */
.magnetic-content {
  padding: 10px 20px 20px;
  overflow-y: auto;
  max-height: 60vh;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* --- 能量模块 (Card) --- */
.energy-module {
  background-color: #f9f9f9;
  border-radius: 16px;
  padding: 4px;
  transition: all 0.3s ease;
  border: 1px solid transparent;
}
.energy-module.active {
  background-color: #fff;
  border-color: #000;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.06);
}
.energy-module.disabled {
  opacity: 0.6;
  pointer-events: none;
}

/* 模块表面 (Face) */
.module-face {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  gap: 16px;
}

.icon-box {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.05);
}
.icon-box.pulse-blue {
  color: #007aff;
}
.icon-box.pulse-orange {
  color: #ff9500;
}
.icon-box svg {
  width: 22px;
  height: 22px;
}

.module-info {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.module-info .name {
  font-size: 16px;
  font-weight: 700;
  color: #1a1a1a;
}
.module-info .desc {
  font-size: 12px;
  color: #888;
  font-weight: 500;
}

/* --- 正负极开关 (Pole Switch) --- */
.pole-switch {
  position: relative;
  width: 64px;
  height: 32px;
  cursor: pointer;
}
.pole-switch input {
  display: none;
}
.pole-switch .track {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: #e0e0e0;
  border-radius: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 8px;
  box-sizing: border-box;
  transition: background-color 0.3s ease;
}
.pole-switch .track .icon-minus, .pole-switch .track .icon-plus {
  font-size: 14px;
  font-weight: 900;
  color: #a0a0a0;
  z-index: 1;
  line-height: 1;
}
.pole-switch .thumb {
  position: absolute;
  left: 4px;
  top: 4px;
  width: 24px;
  height: 24px;
  background-color: #fff;
  border-radius: 50%;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s cubic-bezier(0.5, 1.6, 0.4, 0.7);
  z-index: 2;
}
.pole-switch input:checked + .track {
  background-color: #1a1a1a;
}
.pole-switch input:checked + .track .icon-minus, .pole-switch input:checked + .track .icon-plus {
  color: rgba(255, 255, 255, 0.3);
}
.pole-switch input:checked + .track .thumb {
  transform: translateX(32px);
  background-color: #fff;
}

/* --- 模块详细设置 (折叠区) --- */
.module-settings {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0, 1, 0, 1);
}
.module-settings .inner-padding {
  padding: 0 16px 16px 16px;
  margin-top: 8px;
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  padding-top: 16px;
}

/* 当模块激活时展开设置 */
.energy-module.active .module-settings {
  max-height: 300px;
}

/* --- 设置项组件 --- */
.setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}
.setting-row:last-child {
  margin-bottom: 0;
}
.setting-row .label {
  font-size: 14px;
  color: #555;
  font-weight: 500;
}

.pill-group {
  display: flex;
  background: #eee;
  padding: 3px;
  border-radius: 10px;
}
.pill-group label {
  position: relative;
  cursor: pointer;
}
.pill-group label input {
  display: none;
}
.pill-group label span {
  display: block;
  padding: 6px 14px;
  font-size: 13px;
  border-radius: 8px;
  color: #666;
  transition: all 0.2s;
  font-weight: 500;
}
.pill-group label input:checked + span {
  background: #fff;
  color: #000;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
}

.magnetic-card .action-btn {
  width: 100%;
  padding: 10px;
  border: 1px solid #ddd;
  background: #fff;
  border-radius: 12px;
  color: #1a1a1a;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}
.magnetic-card .action-btn:active {
  background: #f0f0f0;
  transform: scale(0.98);
}

/* --- 时间轮 (Ruler) --- */
.time-wheel-container {
  background: #fff;
  border-radius: 12px;
  padding: 12px;
  border: 1px solid #eee;
}

.wheel-readout {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.wheel-readout .value {
  font-size: 20px;
  font-weight: 700;
  color: #000;
  font-family: monospace;
}

.wheel-ruler-wrapper {
  position: relative;
  height: 50px;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
}
.wheel-ruler-wrapper::-webkit-scrollbar {
  display: none;
}
.wheel-ruler-wrapper::before, .wheel-ruler-wrapper::after {
  content: "";
  position: absolute;
  top: 0;
  width: 20px;
  height: 100%;
  z-index: 2;
  pointer-events: none;
}
.wheel-ruler-wrapper::before {
  left: 0;
  background: linear-gradient(to right, #fff, transparent);
}
.wheel-ruler-wrapper::after {
  right: 0;
  background: linear-gradient(to left, #fff, transparent);
}
.wheel-ruler-wrapper .center-marker {
  position: absolute;
  left: 50%;
  top: 5px;
  bottom: 5px;
  width: 3px;
  background: #ff3b30;
  border-radius: 2px;
  transform: translateX(-50%);
  z-index: 3;
}

/* 找到 #bg-activity-modal-overlay 下的 .ruler-track 样式 */
.ruler-track {
  display: flex;
  padding: 0 50%;
  height: 100%;
  align-items: flex-end;
  width: 1450px;
}
.ruler-track .tick {
  flex-shrink: 0;
  width: 1px;
  background: #ddd;
  margin-right: 9px;
  height: 10px;
}
.ruler-track .tick.hour {
  height: 20px;
  background: #999;
  width: 2px;
  position: relative;
}
.ruler-track .tick.hour::after {
  content: attr(data-hour);
  position: absolute;
  top: -18px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  color: #999;
}
.ruler-track .tick.half {
  height: 15px;
}

.hint-text {
  font-size: 11px;
  color: #999;
  text-align: center;
  margin-top: 8px;
}

/* --- 底部 --- */
.magnetic-footer {
  padding: 20px 24px;
  background: #fff;
  border-top: 1px solid #f4f4f4;
}
.magnetic-footer .save-pill-btn {
  width: 100%;
  padding: 16px;
  border-radius: 50px;
  background: #1a1a1a;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
  transition: transform 0.2s;
}
.magnetic-footer .save-pill-btn:active {
  transform: scale(0.98);
}

