@media (max-width: 600px) {
  /* --- 来电界面 --- */
  .incoming-call-info p {
    /* 【修改】来电提示语（如“AI语音来电...”）字体彻底固定为 14px */
    font-size: 14px;
    margin-top: 0.51vw; /* 2px */
  }
  /* --- 通话中界面 --- */
  .voice-call-header {
    padding-top: var(--status-bar-height, 11.28vw);
  }
  .call-header-btn {
    padding: 2.05vw;
  }
  .call-header-btn svg {
    width: 6.15vw;
    height: 6.15vw;
  }
  .voice-call-main {
    padding: 0 var(--space-md);
  }
  .voice-call-char-info {
    margin-top: 10.25vw;
    margin-bottom: 3.84vw;
  }
  #voice-call-avatar {
    width: 25.64vw;
    height: 25.64vw;
    margin-bottom: var(--space-xl);
  }
  #voice-call-name {
    /* 【修改】大标题字体用 clamp() 严格控制在 22px-24px 之间 */
    font-size: clamp(22px, 6.15vw, 24px);
    margin-bottom: 2.05vw;
  }
  #voice-call-status {
    padding: 1.02vw 3.07vw;
    border-radius: 3.07vw;
  }
  /* --- 输入框和按钮 --- */
  .voice-call-footer {
    gap: 3.84vw;
    padding-bottom: calc(5.12vw + env(safe-area-inset-bottom));
  }
  .voice-call-input-container {
    gap: 2.56vw;
  }
  #voice-call-textarea {
    border-radius: 5.12vw;
    padding: 2.56vw 3.84vw;
    min-height: 5.12vw;
    max-height: 20.51vw;
  }
  #voice-call-send-btn {
    width: 11.28vw;
    height: 11.28vw;
  }
  #voice-call-send-btn svg {
    width: 5.64vw;
    height: 5.64vw;
  }
  .call-action-item {
    gap: 2.05vw;
    width: 20.51vw;
  }
  .call-action-item span {
    /* 【修改】底部按钮下方的文字（如“挂断”）彻底固定为 12px */
    font-size: 12px;
    margin-top: var(--space-xs); /* 使用变量间距 */
  }
  .call-action-btn svg {
    width: 7.17vw;
    height: 7.17vw;
  }
  .call-menu-item {
    padding: 4.1vw;
  }
}
