  justify-content: center;
  align-items: center;
  flex-shrink: 0;
}
.memory-failed-floating-banner .banner-icon svg {
  width: 20px;
  height: 20px;
}
.memory-failed-floating-banner .banner-text {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}
.memory-failed-floating-banner .banner-text span {
