  font-weight: 600;
  color: #d93025;
}
.memory-failed-floating-banner .banner-text span strong {
  font-size: 16px;
}
.memory-failed-floating-banner .banner-text small {
  font-size: 12px;
  color: #e57373;
  margin-top: 2px;
}
.memory-failed-floating-banner .banner-arrow {
