  bottom: -1px;
  z-index: 3;
  width: 7px;
  height: 7px;
  border: 2px solid rgba(255, 255, 255, 0.94);
  border-radius: 50%;
  background: #737e89;
  transform: translateX(-50%);
}
#page-offline-mode.offline-immersive-active .offline-immersive-copy {
  min-width: 0;
  max-width: 142px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
}
#page-offline-mode.offline-immersive-active .offline-immersive-copy strong {
  overflow: hidden;
  color: #30343a;
  font-family: "Songti SC", "STSong", serif;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
