  max-height: 250px;
  overflow-y: auto;
  margin-bottom: 20px;
  scrollbar-width: thin;
  scrollbar-color: #555 #333;
}

/* 隐藏原生复选框 */
.minimal-dark-modal .selection-options-list input[type=checkbox] {
  display: none;
}

/* 自定义复选框的标签样式 */
.minimal-dark-modal .selection-options-list label {
  display: flex;
  align-items: center;
  padding: 12px 0;
