}

/* 自定义复选框的方框 */
.minimal-dark-modal .selection-options-list .checkbox-custom {
  width: 20px;
  height: 20px;
  border: 2px solid #8e8e93;
  border-radius: 4px;
  margin-right: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
