/* --- 外卖页面样式 (强力修复版) --- */
#page-life-food {
  background-color: #F8F8F8;
  position: relative;
  z-index: 1; /* 建立新的层叠上下文 */
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* 1. 顶部导航：极简紧凑版 */
.food-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  /* 【修改】总高度减小到 50px，加上顶部避让其实并不高 */
  height: 50px;
  padding-top: 35px; /* 留给状态栏的空间 */
  display: flex;
  align-items: center; /* 垂直居中 */
  justify-content: center;
  background: transparent;
  z-index: 100;
  transition: all 0.3s ease;
}

.food-header-title {
  font-weight: 600;
  font-size: 16px;
  opacity: 0;
  transform: translateY(5px);
  transition: all 0.3s ease;
  color: #000;
}

/* 滑动后的样式 */
.food-header.scrolled {
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(10px);
  box-shadow: 0 1px 10px rgba(0, 0, 0, 0.05);
  /* 滑动后保持紧凑 */
  padding-top: 35px;
  height: 50px;
}

.food-header.scrolled .food-header-title {
  opacity: 1;
  transform: translateY(0);
}

/* --- 修复：顶栏两侧按钮定位 --- */
/* 1. 强制让左侧返回按钮固定在左下角 */
.food-header .back-button {
  position: absolute !important; /* 加权确保生效 */
  left: 16px;
  bottom: 10px; /* 距离底部的高度，保持垂直居中 */
  z-index: 101;
}

/* 2. 新增：右侧加号按钮样式 */
.food-add-btn {
  position: absolute;
  right: 16px;
  bottom: 10px; /* 与返回按钮保持水平一致 */
  background: transparent;
  border: none;
  padding: 4px; /* 增加一点点击范围 */
  display: flex;
  align-items: center;
  justify-content: center;
  color: #000; /* 黑色图标 */
  z-index: 101;
}

.food-add-btn svg {
  width: 24px;
  height: 24px;
}

/* 2. 内容容器 */
.food-content-wrapper {
  padding: 85px 16px 20px;
  flex: 1;
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
}

/* 顶部 Banner */
.food-header-banner {
  margin-bottom: 12px;
  flex-shrink: 0; /* 防止被压缩 */
}

.food-header-banner h2 {
  font-family: "Didot", serif;
  font-size: 30px; /* 稍微调小一点点让比例更协调 */
  margin: 0;
  color: #000;
  line-height: 1.1;
}

.food-header-banner p {
  font-size: 13px;
  color: #888;
  margin: 4px 0 0;
  letter-spacing: 1px;
}

/* --- 新增：外卖搜索框样式 --- */
.food-search-bar {
  display: flex;
  align-items: center;
  background-color: #fff;
  border: 2px solid #000; /* 黑色边框，保持生活页风格 */
  border-radius: 30px; /* 圆润造型 */
  padding: 10px 16px;
  margin-bottom: 20px; /* 这里的间距很重要，推开下面的分类栏 */
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.03);
}

.food-search-bar svg {
  width: 18px;
  height: 18px;
  stroke: #000;
  margin-right: 10px;
  opacity: 0.6;
}

.food-search-bar input {
  flex-grow: 1;
  border: none;
  background: transparent;
  outline: none;
  font-size: 14px;
  color: #000;
  font-weight: 500;
}

.food-search-bar input::placeholder {
  color: #aaa;
}

/* 3. 分类栏 (解决遮挡的核心) */
.food-category-scroll {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  /* 【强力修复】强制占高，防止高度塌陷 */
  min-height: 40px;
  padding: 2px 2px 10px 2px; /* 底部留白给滚动条/阴影 */
  /* 【强力修复】强制推开下方的瀑布流 */
  margin-bottom: 20px;
  /* 【强力修复】提高层级，压在瀑布流上面 */
  position: relative;
  z-index: 10;
  scrollbar-width: none;
  -ms-overflow-style: none;
  flex-shrink: 0; /* 禁止被压缩 */
}

.food-category-scroll::-webkit-scrollbar {
  display: none;
}

.cat-pill {
  flex-shrink: 0;
  padding: 6px 14px;
  border-radius: 18px; /* 稍微圆润一点 */
  font-size: 12px; /* 字体精致一点 */
  font-weight: 500;
  color: #555;
  background: #fff;
  border: 1px solid #f0f0f0;
  transition: all 0.2s;
  /* 确保每个按钮都有高度 */
  height: fit-content;
}

.cat-pill.active {
  background: #000;
  color: #fff;
  border-color: #000;
  font-weight: 600;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.15);
}

/* 4. 瀑布流布局 */
.food-masonry-grid {
  column-count: 2;
  column-gap: 12px;
  width: 100%;
  /* 【强力修复】降低层级，确保不遮挡上面 */
  position: relative;
  z-index: 1;
}

.food-card {
  /* 防止卡片内部断裂 */
  break-inside: avoid;
  -webkit-column-break-inside: avoid;
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
  /* 解决部分浏览器渲染重叠问题 */
  transform: translateZ(0);
}

.card-img {
  width: 100%;
  background-size: cover;
  background-position: center;
  position: relative;
}

