/* --- 购物页吊牌弹窗样式 --- */
.shop-tag-card {
  width: 280px;
  background: #fff;
  border-radius: 4px; /* 稍微方一点，像硬卡纸 */
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  padding: 20px 20px 15px;
  position: relative;
  display: flex;
  flex-direction: column;
  /* 动画：像吊牌一样摆动出现 */
  animation: swingIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform-origin: top right;
}

@keyframes swingIn {
  0% {
    transform: rotate(-10deg) translateY(-20px);
    opacity: 0;
  }
  100% {
    transform: rotate(0) translateY(0);
    opacity: 1;
  }
}
/* 装饰孔 */
.tag-hole {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 12px;
  height: 12px;
  background: #333;
  border-radius: 50%;
  border: 2px solid #e0e0e0;
}

/* 装饰线 (假装连着按钮) */
.tag-string {
  position: absolute;
  top: -60px;
  right: 20px;
  width: 2px;
  height: 80px;
  background: #333;
  z-index: -1;
}

/* 顶部 Tab */
.tag-tabs {
