  border-bottom: 2px solid #000;
  margin-bottom: -2px;
}

/* 内容区 */
.tag-content {
  display: none;
  flex-direction: column;
  gap: 12px;
}
.tag-content.active {
  display: flex;
}

/* 输入框样式 */
