/* ===============================================
   ▼▼▼ 【新增】查手机密码锁屏样式 (日杂极简风) ▼▼▼
   =============================================== */
.phone-lock-container {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-radius: 8px;
  padding: 40px 30px 30px;
  width: 80%;
  max-width: 300px;
  text-align: center;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
  font-family: "Helvetica Neue", Arial, sans-serif;
}
.phone-lock-container.shake {
  animation: lock-shake 0.4s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}
.phone-lock-container .lock-icon {
  margin-bottom: 15px;
}
.phone-lock-container .lock-icon svg {
  width: 32px;
  height: 32px;
  stroke: #1a1a1a;
}
.phone-lock-container #lock-name {
  font-size: 20px;
  font-weight: 300;
  color: #1a1a1a;
  margin: 0 0 5px;
  letter-spacing: 2px;
}
.phone-lock-container .lock-hint {
  font-size: 10px;
  color: #aaa;
  letter-spacing: 3px;
  margin: 0 0 30px;
}
.phone-lock-container .lock-input {
  width: 100%;
  background: transparent;
  border: none;
  border-bottom: 2px solid #1a1a1a;
  padding: 10px 0;
  font-size: 24px;
  font-family: "Courier New", Courier, monospace;
  text-align: center;
  color: #1a1a1a;
  letter-spacing: 8px;
  outline: none;
  margin-bottom: 10px;
  transition: border-color 0.3s;
}
.phone-lock-container .lock-input::placeholder {
  font-size: 12px;
  letter-spacing: 1px;
  color: #ccc;
  font-family: -apple-system, sans-serif;
}
.phone-lock-container .lock-input:focus {
  border-bottom-color: #d4a373;
}
.phone-lock-container .lock-error {
  font-size: 10px;
  color: #d0021b;
  height: 14px;
  margin-bottom: 30px;
  letter-spacing: 1px;
}
.phone-lock-container .lock-actions {
  display: flex;
  gap: 10px;
}
.phone-lock-container .lock-actions button {
  flex: 1;
  padding: 12px 0;
  border: none;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  cursor: pointer;
  transition: 0.2s;
}
.phone-lock-container .lock-actions button#lock-cancel-btn {
  background: #f5f5f5;
  color: #666;
  border-radius: 4px;
}
.phone-lock-container .lock-actions button#lock-confirm-btn {
  background: #1a1a1a;
  color: #fff;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.3s;
}
.phone-lock-container .lock-actions button#lock-confirm-btn.loading {
  background: #444;
  color: #aaa;
  pointer-events: none;
}
.phone-lock-container .lock-actions button#lock-confirm-btn.loading::before {
  content: "";
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-top-color: #fff;
  border-radius: 50%;
  animation: lock-btn-spin 0.8s linear infinite;
}
.phone-lock-container .lock-actions button:active {
  transform: scale(0.96);
}

@keyframes lock-shake {
  10%, 90% {
    transform: translate3d(-1px, 0, 0);
  }
  20%, 80% {
    transform: translate3d(2px, 0, 0);
  }
  30%, 50%, 70% {
    transform: translate3d(-4px, 0, 0);
  }
  40%, 60% {
    transform: translate3d(4px, 0, 0);
  }
}
@keyframes lock-btn-spin {
  to {
    transform: rotate(360deg);
  }
}
/* ===============================================
   ▼▼▼ LoverSync 标记与弹窗高级样式 ▼▼▼
   =============================================== */
/* 1. 高级折角标记样式 */
.lover-sync-pinned {
  position: relative !important;
  outline: 2px solid #1a1a1a !important; /* 纯黑边框 */
  outline-offset: -2px;
  border-radius: inherit;
  transition: outline 0.2s ease;
  /* 右上角的黑色折角 */
}
.lover-sync-pinned::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 24px 24px 0;
  border-color: transparent #1a1a1a transparent transparent;
  z-index: 100;
}
.lover-sync-pinned {
  /* 白色的对勾 */
}
.lover-sync-pinned::before {
  content: "✓";
  position: absolute;
  top: 1px;
  right: 3px;
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  z-index: 101;
}

/* 防止气泡圆角盖不住折角 */
.msg-bubble.lover-sync-pinned {
  overflow: hidden;
}

