  overflow: hidden;
  position: absolute;
  height: 42px;
  border-radius: 21px;
  display: flex;
  align-items: center;
  padding: 0 10px;
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  white-space: nowrap;
  z-index: 4;
}
