/* 淇敼澶勫墠涓よ */
.truncate-text {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  /* 銆愪慨鏀广€戜紭鍖栨崲琛岄€昏緫锛岄槻姝㈣嫳鏂?鏁板瓧鎴柇澶笐锛屽苟闃叉琚玣lex鍘嬬缉 */
  word-break: break-word;
  white-space: normal;
  flex-shrink: 0;
  /* 榧犳爣鍙樻垚灏忔墜锛屾殫绀哄彲浠ョ偣鍑?*/
  cursor: pointer;
}

/* 淇敼澶勫悗涓よ */
/* 闄愬埗鏈€澶氭樉绀?琛?*/
.truncate-text[data-lines="2"] {
  -webkit-line-clamp: 2;
}

/* 鎮诞姘旀场妗嗙殑绮剧編鏍峰紡 */
.cs-text-tooltip {
  position: fixed;
  z-index: 9999;
  left: 50% !important;
  background: rgba(74, 68, 64, 0.95);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: #FDFCF9;
  /* 淇敼澶勫墠涓よ */
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.5;
  width: auto;
  max-width: 80vw;
  white-space: normal;
  word-wrap: break-word;
  box-shadow: 0 10px 24px rgba(92, 84, 77, 0.25);
  pointer-events: none; /* 闃叉閬尅涓嬫柟鐐瑰嚮 */
  /* 鍔ㄧ敾鍒濆鐘舵€佷笌瀹氫綅鍋忕Щ */
  opacity: 0;
  transform: translate(-50%, calc(-100% + 10px));
  transition: all 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.cs-text-tooltip.show {
  opacity: 1;
  /* 鍚戜笂娴嚭鐨勬晥鏋?*/
  transform: translate(-50%, -100%);
}
.cs-text-tooltip {
  /* 搴曢儴鐨勬寚寮曞皬涓夎 */
}
.cs-text-tooltip::after {
  content: "";
  position: absolute;
  bottom: -5px;
  left: 50%;
  margin-left: -5px;
  border-width: 5px 5px 0;
  border-style: solid;
  border-color: rgba(74, 68, 64, 0.95) transparent transparent transparent;
}

