.period-fullscreen-confirm {
  position: fixed;
  inset: 0;
  z-index: 20000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: rgba(253, 247, 247, 0.96);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: #D3A7A5;
  opacity: 0;
  pointer-events: none;
  transform: scale(1.02);
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.period-fullscreen-confirm.show {
  opacity: 1;
  transform: scale(1);
}
.period-fullscreen-confirm.leave {
  opacity: 0;
  transform: scale(0.98);
}
.period-fullscreen-confirm .period-confirm-orbit {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  border: 1px dashed rgba(211, 167, 165, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 18px 45px rgba(211, 167, 165, 0.16);
  animation: period-full-orbit 0.86s ease forwards;
}
.period-fullscreen-confirm .period-confirm-core {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: #FFF;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 0 8px #FDE8E8, 0 12px 30px rgba(211, 167, 165, 0.16);
  animation: period-full-core 0.86s ease forwards;
}
.period-fullscreen-confirm .period-confirm-core svg {
  width: 44px;
  height: 44px;
  color: #D3A7A5;
  animation: period-full-check 0.52s ease 0.14s both;
}
.period-fullscreen-confirm .period-confirm-text {
  color: #6E5C53;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0;
}

@keyframes period-full-orbit {
  0% {
    opacity: 0;
    transform: scale(1.22) rotate(18deg);
  }
  40% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(0deg);
  }
}
@keyframes period-full-core {
  0% {
    transform: scale(0.72);
  }
  55% {
    transform: scale(1.08);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes period-full-check {
  0% {
    opacity: 0;
    transform: scale(0.6);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
