.touch-container {
  /* ▼▼▼ 修改：带有小尾巴的可爱对话气泡与动态效果 ▼▼▼ */
}
.touch-container .touch-response-toast {
  position: absolute;
  bottom: 120px;
  background: rgba(255, 253, 245, 0.95);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: #6E5C53;
  padding: 12px 24px;
  border-radius: 24px 24px 24px 4px; /* 重点：左下角变成直角，形成对话气泡的小尾巴 */
  border: 2px solid #F2EAE4;
  box-shadow: 0 8px 24px rgba(211, 167, 165, 0.25);
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 1px;
  opacity: 0;
  transform: translateY(20px) scale(0.8);
  transition: opacity 0.3s ease, transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); /* 果冻回弹动画 */
  z-index: 30;
  pointer-events: none;
  transform-origin: bottom left;
}
.touch-container {
  /* 1. 普通出现状态 */
}
.touch-container .touch-response-toast.show {
  opacity: 1;
  transform: translateY(0) scale(1);
}
.touch-container {
  /* 2. 双击触发的“生气震动”状态 */
}
.touch-container .touch-response-toast.show.shake {
  animation: toastShake 0.4s ease-in-out;
}
.touch-container {
  /* 3. 长按触发的“心动扑通”状态 */
}
.touch-container .touch-response-toast.show.scale {
  animation: toastHeartbeat 0.8s ease-in-out;
}
@keyframes toastShake {
  0%, 100% {
    transform: translateX(0) rotate(0deg);
  }
  25% {
    transform: translateX(-6px) rotate(-3deg);
  }
  50% {
    transform: translateX(6px) rotate(3deg);
  }
  75% {
    transform: translateX(-6px) rotate(-3deg);
  }
}
@keyframes toastHeartbeat {
  0%, 100% {
    transform: scale(1);
  }
  30% {
    transform: scale(1.08);
  }
  50% {
    transform: scale(1.02);
  }
  70% {
    transform: scale(1.12);
  }
}
