html.looky-native body.android-viewport-sync #page-looky-pay .lp-header {
  padding-top: calc(max(env(safe-area-inset-top, 0px), var(--looky-native-status-bar-height, 0px), 20px) + var(--app-page-offset-pull-up, 0px));
}

html.looky-native body.android-viewport-sync #page-looky-pay .lp-floating-nav {
  translate: 0 calc(var(--app-bottom-offset, 0px) - max(0px, var(--looky-native-navigation-bar-height, 0px) - env(safe-area-inset-bottom, 0px))) !important;
}

html.looky-native body.android-viewport-sync #page-looky-pay .lp-content-wrapper {
  padding-bottom: calc(100px + max(0px, var(--looky-native-navigation-bar-height, 0px) - env(safe-area-inset-bottom, 0px)));
}

