  color: #111;
  border-radius: 18px;
  padding: 15px 0 14px;
  margin-top: 10px;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  user-select: none;
  -webkit-user-select: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 8px 18px rgba(0, 0, 0, 0.05);
  transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
#lp-payment-modal .lp-fingerprint-mark {
  position: relative;
  width: 76px;
  height: 76px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #fff, #eef1f3);
  border: 1px solid rgba(0, 0, 0, 0.08);
  overflow: hidden;
  box-shadow: inset 0 1px 5px rgba(255, 255, 255, 0.85), inset 0 -8px 16px rgba(0, 0, 0, 0.04), 0 8px 20px rgba(0, 0, 0, 0.08);
}
#lp-payment-modal .lp-fingerprint-ring {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 8px solid currentColor;
  box-sizing: border-box;
  box-shadow: inset 0 0 0 9px rgba(255, 255, 255, 0.96);
}
#lp-payment-modal .lp-fingerprint-text {
  font-size: 12px;
  color: #555;
  letter-spacing: 0;
}
#lp-payment-modal .lp-fingerprint-btn.holding {
  background: #111;
  color: #fff;
  border-color: #111;
  transform: scale(0.98);
}
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-mark {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.25);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06), 0 0 24px rgba(255, 255, 255, 0.14);
}
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-mark::before,
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-mark::after {
  content: "";
  position: absolute;
  inset: 50%;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.55);
  transform: translate(-50%, -50%) scale(0.4);
  animation: lpFingerprintRipple 0.9s ease-out infinite;
}
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-mark::after {
  animation-delay: 0.28s;
}
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-ring {
  box-shadow: inset 0 0 0 9px rgba(17, 17, 17, 0.92);
}
#lp-payment-modal .lp-fingerprint-btn.holding .lp-fingerprint-text {
  color: #fff;
}

/* 虚拟卡片创建弹窗弹出动画 */
@keyframes lpModalPop {
  from {
    opacity: 0;
    transform: scale(0.85) translateY(20px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}
/* 虚拟卡片生成动画 */
#lp-card-progress-modal #lp-progress-spinner {
  display: none !important;
}

#lp-card-progress-modal .lp-printer-anim {
  position: relative;
  width: 220px;
  height: 160px;
  margin-bottom: 25px;
}

#lp-card-progress-modal .lp-printer-body {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 220px;
  height: 80px;
  background: linear-gradient(180deg, #3a3a3e, #232327);
  border-radius: 16px;
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.08), 0 12px 25px rgba(0, 0, 0, 0.45);
  z-index: 3;
}

#lp-card-progress-modal .lp-printer-slot {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  width: 172px;
  height: 8px;
  background: #0a0a0a;
  border-radius: 4px;
  box-shadow: inset 0 2px 3px rgba(0, 0, 0, 0.9);
}

#lp-card-progress-modal .lp-printer-body::after {
  content: "";
  position: absolute;
  bottom: 14px;
  left: 22px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 8px #4ade80;
  animation: lpBlink 1.2s infinite;
}

/* ▼▼▼ 把原来的 .lp-ejecting-card 等区域及 @keyframes 替换成以下这段（开启 GPU 加速） ▼▼▼ */
#lp-card-progress-modal .lp-ejecting-card {
  position: absolute;
  top: 0;
  left: 50%;
  margin-left: -80px;
  width: 160px;
  height: 105px;
  border-radius: 12px;
  background: linear-gradient(135deg, #2a2a2a, #0a0a0a 60%, #333);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.6);
  z-index: 2;
  padding: 14px;
  box-sizing: border-box;
  animation: lpEjectCard 3s ease-in-out infinite;
  will-change: transform, opacity; /* 强制硬件加速 */
}

#lp-card-progress-modal .lp-card-chip-mini {
  width: 30px;
  height: 22px;
  border-radius: 5px;
  background: linear-gradient(135deg, #e0e0e0, #888);
  border: 1px solid #111;
}

#lp-card-progress-modal .lp-card-lines {
  position: absolute;
  left: 14px;
  bottom: 16px;
  width: 65%;
  height: 7px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.3);
  box-shadow: 0 13px 0 rgba(255, 255, 255, 0.15);
}

@keyframes lpEjectCard {
  0% {
    transform: translateY(80px);
    opacity: 0;
  }
  15% {
    transform: translateY(80px);
    opacity: 1;
  }
  55% {
    transform: translateY(-28px);
    opacity: 1;
  }
  85% {
    transform: translateY(-28px);
    opacity: 1;
  }
  100% {
    transform: translateY(80px);
    opacity: 0;
  }
}
@keyframes lpBlink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
