/* 独立顶栏，适配安全区 */
.forum-discover-header {
  padding: calc(var(--status-bar-height, 44px) + 12px) 20px 16px;
  background: rgba(253, 253, 253, 0.9);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.forum-discover-header .dh-top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.forum-discover-header .dh-top-row .dh-title-group {
  display: flex;
  flex-direction: column;
}
