  font-size: 10px;
  color: #a0a0a0;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-top: 2px;
}
.forum-discover-header .dh-top-row .dh-actions {
  position: relative;
  display: flex;
  gap: 12px;
}
.forum-discover-header .dh-top-row .dh-actions .icon-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  border: 1px solid #f0f0f0;
  border-radius: 12px;
  color: #333;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.02);
}
.forum-discover-header .dh-top-row .dh-actions .icon-btn svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.5;
}
.forum-discover-header .dh-top-row .dh-actions .icon-btn:active {
  transform: scale(0.95);
  background: #f9f9f9;
}
.forum-discover-header .dh-search {
  position: relative;
  display: flex;
  align-items: center;
  background: #f6f6f6;
  border-radius: 12px;
  padding: 10px 16px;
  gap: 10px;
  color: #888;
  font-size: 14px;
}
.forum-discover-header .dh-search svg {
  width: 16px;
  height: 16px;
  stroke-width: 2;
  opacity: 0.6;
}
.forum-discover-header .dh-search input {
  border: none;
  background: transparent;
  outline: none;
  width: 100%;
  font-size: 14px;
  color: #333;
}
