  color: #aaa;
}
.forum-discover-header .dh-search-results {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 8px);
  z-index: 30;
  border: 1px solid #eeeeee;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.08);
  overflow: hidden;
}
.forum-discover-header .dh-search-result {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: 0;
  border-bottom: 1px solid #f4f4f4;
  background: #fff;
  padding: 10px 12px;
  text-align: left;
  cursor: pointer;
}
.forum-discover-header .dh-search-result:last-child {
  border-bottom: 0;
}
.forum-discover-header .dh-search-result:active {
  background: #f8f8f8;
}
.forum-discover-header .dh-search-result img,
.forum-discover-header .dh-search-result .dh-search-result-icon {
