}

.cl-detail-actions button.is-disabled {
  color: rgba(0, 0, 0, 0.36);
  background: rgba(255, 255, 255, 0.56);
}

.cl-detail-request-panel {
  border: 1px solid rgba(0, 0, 0, 0.13);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.86);
  padding: 14px;
