}

.cl-detail-request-panel > div:first-child {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.cl-detail-request-panel strong {
  font-size: 14px;
  font-weight: 850;
}

.cl-detail-request-panel span {
  color: rgba(0, 0, 0, 0.38);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.cl-detail-request-panel p {
  margin: 8px 0 12px;
  color: rgba(0, 0, 0, 0.52);
  font-size: 12px;
  line-height: 1.55;
}

.cl-detail-request-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.cl-detail-request-actions button {
  min-height: 38px;
  border-radius: 10px;
  border: 1px solid rgba(0, 0, 0, 0.14);
  background: #efeff0;
  color: #111;
  font-size: 13px;
  font-weight: 850;
}

.cl-detail-request-actions button:last-child {
