  font-weight: 850;
}

.cl-detail-section-title small {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(0, 0, 0, 0.26);
}

.cl-detail-meter {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
