.cl-detail-meter div {
  min-width: 0;
  min-height: 68px;
  border: 1px solid rgba(0, 0, 0, 0.09);
  border-radius: 12px;
  background: rgba(238, 242, 246, 0.72);
  padding: 11px;
}

.cl-detail-meter strong,
.cl-detail-meter span {
