}

.cl-detail-meter strong {
  font-size: 24px;
  line-height: 1;
  font-weight: 850;
  overflow-wrap: anywhere;
}

.cl-detail-meter span {
  margin-top: 8px;
  font-size: 11px;
  font-weight: 700;
  color: rgba(0, 0, 0, 0.36);
